using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "MyDatabase");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The default discriminator value changed from
        // the short class name ("Product") to the full CLR type name (namespace-qualified).
        // Existing documents store "Product" — explicitly configure to keep compatibility.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Product>("Product");

        modelBuilder.Entity<Product>()
            .ToContainer("Products")
            .HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 breaking change: The Cosmos provider no longer supports synchronous
    // I/O (e.g. ToList(), First(), Count()). All queries must use async equivalents.
    // Sync calls now throw InvalidOperationException at runtime.

    // BEFORE (EF Core 8 — sync, now broken):
    // List<Product> GetProducts(CosmosDbContext db)
    //     => db.Products.Where(p => p.Category == "Books").ToList();

    // AFTER (EF Core 9 — async):
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
        => await db.Products.Where(p => p.Category == "Books").ToListAsync();

    // BEFORE (sync):
    // Product? GetFirst(CosmosDbContext db)
    //     => db.Products.FirstOrDefault(p => p.Id == "1");

    // AFTER (async):
    async Task<Product?> GetFirstAsync(CosmosDbContext db)
        => await db.Products.FirstOrDefaultAsync(p => p.Id == "1");
}

